import 'dotenv/config';
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { client, getGames, getCalendar } from 'cfbd';
import type { DemoGame, DemoGameData, DemoWeek } from '../demo/seedData.js';
import { COMPLETED_THROUGH_WEEK, CURATION_WEEK, DEMO_YEAR } from '../demo/seedData.js';

// One-off export of the demo's game data from CFBD into src/demo/demoGameData.ts.
// Run: CFBD_API_KEY=... pnpm export:demo-games
// Commit the generated file; the demo never calls CFBD at runtime.
//
// Weeks 1..COMPLETED_THROUGH_WEEK keep their real final scores. Later weeks have results
// stripped so they look like upcoming games.

const GAMES_PER_WEEK = 8;

// Well-known programs, so the demo shows games a visitor will recognise.
const FEATURED = new Set([
  'Alabama', 'Georgia', 'Ohio State', 'Michigan', 'Texas', 'Oregon', 'Notre Dame', 'Penn State',
  'Clemson', 'Florida State', 'LSU', 'Tennessee', 'USC', 'Oklahoma', 'Miami', 'Florida',
  'Auburn', 'Texas A&M', 'Ole Miss', 'Missouri', 'Utah', 'Washington', 'Wisconsin', 'Iowa',
  'Nebraska', 'Kansas State', 'Louisville', 'Virginia Tech', 'North Carolina', 'Arkansas',
  'South Carolina', 'Kentucky', 'Colorado', 'Boise State', 'SMU', 'Texas Tech', 'Oklahoma State',
  'Michigan State', 'UCLA', 'Georgia Tech',
]);

async function main() {
  const apiKey = process.env.CFBD_API_KEY;
  if (!apiKey) {
    console.error('export-demo-games: CFBD_API_KEY is required');
    process.exit(1);
  }
  client.setConfig({ headers: { Authorization: `Bearer ${apiKey}` } });

  const calendar = (await getCalendar({ query: { year: DEMO_YEAR } })).data ?? [];
  const weeks: DemoWeek[] = [];
  const games: DemoGame[] = [];

  for (let week = 1; week <= CURATION_WEEK; week++) {
    const cal = calendar.find(w => w.seasonType === 'regular' && w.week === week);
    if (!cal) throw new Error(`CFBD calendar has no regular-season week ${week} for ${DEMO_YEAR}`);
    weeks.push({
      weekNumber: week,
      year: DEMO_YEAR,
      seasonType: 'regular',
      weekStart: cal.startDate.slice(0, 10),
      weekEnd: cal.endDate.slice(0, 10),
    });

    const result = (
      await getGames({ query: { year: DEMO_YEAR, week, seasonType: 'regular', classification: 'fbs' } })
    ).data ?? [];

    const final = week <= COMPLETED_THROUGH_WEEK;
    const candidates = result
      .filter(g => g.startDate && g.homeTeam && g.awayTeam)
      .filter(g => !final || (g.completed && g.homePoints != null && g.awayPoints != null))
      // Marquee games (both teams featured) first, then one featured team, then earliest kickoff.
      .map(g => ({
        g,
        score: (FEATURED.has(g.homeTeam) ? 1 : 0) + (FEATURED.has(g.awayTeam) ? 1 : 0),
      }))
      .filter(x => x.score > 0)
      .sort((a, b) => b.score - a.score || a.g.startDate.localeCompare(b.g.startDate))
      .slice(0, GAMES_PER_WEEK)
      .map(x => x.g)
      .sort((a, b) => a.startDate.localeCompare(b.startDate));

    if (candidates.length < GAMES_PER_WEEK) {
      console.warn(`  week ${week}: only ${candidates.length} featured games found`);
    }

    for (const g of candidates) {
      games.push({
        cfbdGameId: g.id,
        weekNumber: week,
        homeTeam: g.homeTeam,
        awayTeam: g.awayTeam,
        startTime: new Date(g.startDate).toISOString(),
        completed: final,
        homePoints: final ? (g.homePoints ?? null) : null,
        awayPoints: final ? (g.awayPoints ?? null) : null,
        spread: null,
      });
    }
    console.log(`  week ${week}: ${candidates.length} games`);
  }

  const data: DemoGameData = { weeks, games };
  const outPath = fileURLToPath(new URL('../demo/demoGameData.ts', import.meta.url));
  const body =
    `import type { DemoGameData } from './seedData.js';\n\n` +
    `// GENERATED by \`pnpm export:demo-games\` from CFBD ${DEMO_YEAR} data. Do not edit by hand.\n` +
    `export const demoGameData: DemoGameData = ${JSON.stringify(data, null, 2)};\n`;
  writeFileSync(outPath, body);
  console.log(`export-demo-games: wrote ${games.length} games to ${outPath}`);
}

main().catch(err => {
  console.error('export-demo-games failed:', err);
  process.exit(1);
});
